package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

var pythonServiceNames = map[string]string{
	"baremetalintrospection": "baremetal_introspection", "blockstorage": "block_storage",
	"containerinfra": "container_infrastructure_management", "db": "database",
	"keymanager": "key_manager", "loadbalancer": "load_balancer", "messaging": "message",
	"objectstorage": "object_store", "sharedfilesystems": "shared_file_system",
	"instanceha": "instance_ha",
}

var exampleResources = map[string]string{
	"baremetal": "nodes", "blockstorage": "volumes", "compute": "servers", "containerinfra": "clusters", "db": "instances",
	"dns": "zones", "identity": "users", "image": "images", "keymanager": "secrets", "loadbalancer": "loadbalancers",
	"network": "networks", "placement": "resourceproviders", "reservation": "leases", "sharedfilesystems": "shares", "workflow": "workflows",
	"instanceha": "segments", "clustering": "profiletypes",
}

// Versioned reference pages are derived from the same API and resource inventory
// as the code, keeping registry fields and common-policy coverage reviewable.
func (g *generator) writeServiceREADME(key string, spec serviceSpec, paths []string) error {
	parts := strings.Split(key, "/")
	python := pythonServiceNames[parts[0]]
	if python == "" {
		python = parts[0]
	}
	method := spec.name + strings.ToUpper(parts[1][:1]) + parts[1][1:]
	var out strings.Builder
	fmt.Fprintf(&out, "# %s %s\n\n<!-- Generated by sdkgen; edit internal/cmd/sdkgen/service_docs.go. -->\n\n", spec.name, parts[1])
	sdkOwnedService := parts[0] == "clustering" || parts[0] == "instanceha"
	if sdkOwnedService {
		fmt.Fprintf(&out, "%s is implemented by this SDK because pinned Gophercloud does not provide it. The resources below follow pinned openstacksdk and the official API contracts through one authenticated service object. Connection manages authentication, region, endpoint interface and TLS.\n\n", key)
	} else {
		fmt.Fprintf(&out, "Use Gophercloud v2.15.0's %s API through one authenticated service object. Connection manages authentication, region, endpoint interface and TLS.\n\n", key)
	}
	pythonAccess := "`conn." + python + "`"
	if parts[0] == "metric" {
		pythonAccess = "No directly corresponding service (Aetos)"
	}
	fmt.Fprintf(&out, "Service access: `conn.%s(ctx)` (openstacksdk: %s).", method, pythonAccess)
	if sdkOwnedService {
		out.WriteString(" Responses keep original fields, HTTP headers and status codes.")
	}
	out.WriteString("\n\n")
	if key == "blockstorage/v2" {
		out.WriteString("Selected stateful resources provide `WaitForState(ctx, ref, target, options...)` and `WaitForDelete(ctx, ref, options...)`. State waits use the service's exact ERROR/error failure defaults and no SDK timeout; deletion observation defaults to 120 seconds, with a 2-second interval. Compute Server `WaitForServer` defaults to ACTIVE and 120 seconds; Cinder Volume/Snapshot `WaitForAvailable` defaults to available. Caller `resource.With...` options apply last. Common `WaitFor/WaitForDeletion` retain their 5-minute default; native `WaitForStatus` has a separate contract. See [wait policies](../../docs/service-waits.md).\n\n")
	}
	if key == "image/v2" {
		out.WriteString("Package docs describe the image workflows and the v2 service (`go doc ./image/` and `go doc ./image/v2/...`). Guides: [wait policies](../../docs/service-waits.md), [image task comparison](image-tasks-python.md), [direct upload](../upload-image.md), [image updates](../update.md), [image reads](../images.md), [image tasks](../image-tasks.md), [tasks](../tasks.md), [members](../members.md), [native members](members/README.md), [cache](../cache.md), [schemas](../schemas.md), [schema records](../schema-records.md), [locations](../locations.md), [tag/state changes](../mutations.md), [service information](serviceinfo/README.md), [usage](serviceinfo/usage.md), [deletion](../delete.md), [downloads](../download.md), [create/import](../create-import.md), [staging](imagedata/README.md), [task waiting/recreation](tasks/README.md), [import](imageimport/README.md), [identity finding](../../docs/finding-identities.md)." + "\n\n")
	}
	if parts[0] == "metric" {
		out.WriteString("This version implements the Aetos Prometheus API, not the same functionality as Python openstacksdk's Gnocchi metric service.\n\n")
	}
	identityFindAccess := map[string]string{
		"dns/v2":          "`FindIdentity` on the scope returned by `RecordSets.InZone(ctx, parent)`",
		"loadbalancer/v2": "`FindIdentity` on the scope returned by `Pools.Members(ctx, parent)`",
	}
	if access, ok := identityFindAccess[key]; ok {
		fmt.Fprintf(&out, "%s resolves name/ID strings automatically, with list fallback after GET400/403/404, exact ID/name and duplicate checks, and a default missing result of `nil, nil`. Select strict handling with `resource.WithIdentityFindIgnoreMissing(false)`. Caller `WithIdentityFindQuery` filters survive GET and fallback listing; automatic name hints apply only to listing. Concrete options control query/fallback. See [identity finding](../../docs/finding-identities.md) for binding, fixed parents, domain filters and path policy.\n\n", access)
	}
	if key == "keymanager/v1" {
		out.WriteString("Package docs describe the service and each resource (`go doc ./keymanager/v1/...`), including the SDK-owned Fetch, CreateRecord, Remove, ListRecords, payload and identity calls, secret stores, quotas and waits.\n\n")
	}
	if key == "messaging/v2" {
		out.WriteString("`Subscriptions.InQueue(ctx, queueName)` fixes the caller's queue name without lookup. Create/Get/List/All return SDK-owned Subscription models; Delete returns only error. POST201 preserves optional subscription_id and actual raw output. Location may be a collection URL and is not followed or treated as an item ID. A stable connection Client-ID is used; listing follows Python MessageResource row-count limit/last-ID marker rules. See [subscriptions](subscriptions/README.md) for per-call project headers, omitted TTL, consumption controls, delete404 defaults and remaining Resource/cache contracts.\n\n")
	}
	switch key {
	case "instanceha/v1":
		out.WriteString("Masakari uses service type instance-ha, preserving catalog `/v1/{project}` and reverse-proxy prefixes. Route IDs are UUIDs; database IDs remain raw data. Segments enabled input requires numeric microversion >=1.2; `VMoves.InNotification(ctx, ref)` requires >=1.3. See [segments](segments/README.md), [hosts](hosts/README.md), [notifications](notifications/README.md), [VMoves](vmoves/README.md) for 15 resource operations and [waiting](waiting/README.md) for two proxy waits. Fetchable resources provide `WaitForStatus/WaitForDelete`: unlimited state waits with ERROR failure/2-second intervals and 120-second deletion waits. Host/VMove retain fixed parents; VMove GET rechecks >=1.3. APIs cover all 17 direct declarations; marker fallback, nullable inputs and full Resource/cache contracts need further comparison.\n\n")
	case "clustering/v1":
		out.WriteString("Package docs describe the service and each resource (`go doc ./clustering/v1/...`). [Identity lookup](finding/README.md), [list controls](listing/README.md), [waits](waiting/README.md), [tracking](tracking/README.md) and [update scopes](scoping/README.md) cover behavior shared by several resources.\n\n")
	case "baremetal/v1":
		out.WriteString("`Nodes.GetVirtualMedia` returns the SDK `VirtualMedia` model with the attached image, insertion state, and media types. See [virtual media reads](nodes/README.md).\n\n")
		out.WriteString("`Conductors.Resources` uses `Conductor.Hostname` as both ID and name. `resource.ID(\"conductor-01\")` performs a direct read; `resource.Name(\"conductor-01\")` searches the complete inventory for an exact match. `Drivers.Resources` uses `Driver.Name` as ID and name. Both resources support reads, listing, and name lookup only; deletion and status waits return `ErrUnsupported`. See [conductors](conductors/README.md) and [drivers](drivers/README.md).\n\n")
		out.WriteString("Conductor endpoints require microversion 1.49 or later. Configure `sdk.WithMicroversion(sdk.BareMetal, \"1.49\")` or `sdk.WithMicroversionRange(sdk.BareMetal, \"1.49\", \"latest\")`. Calling the operation does not automatically increase the connection version. See [Conductor version requirements and API references](conductors/README.md).\n\n")
	case "baremetalintrospection/v1":
		out.WriteString("`Introspection.Resources` fetches and lists using the node UUID without assuming Name, Status, or Delete support. `Introspection.WaitUntilFinished(ctx, ref, waitOptions...)` waits for `Finished` and preserves the actual `Error` in `IntrospectionFailureError`. The SDK-owned `StartIntrospection` helper corrects query omission in the pinned native function, forwarding nil/false/true `ManageBoot` and extension queries. See [start, get, and completion waits](introspection/README.md).\n\n")
	case "identity/v2":
		out.WriteString("`Tokens.Create/Get` returns the SDK-owned `Authentication`. It parses `Token`, `User`, and `Catalog` together and preserves `Header` and the JSON `Body`, including additional response fields. See [authentication responses](tokens/README.md).\n\n")
		out.WriteString("Keystone v2.0 was removed in Queens and works only on older deployments." + "\n\n")
		out.WriteString("See [Python Proxy mappings](python-parity.md) for openstacksdk identity v2 methods." + "\n\n")
	case "placement/v1":
	case "identity/v3":
		out.WriteString("Package docs describe the service and its resources (`go doc ./identity/v3/...`). SDK-owned [`EndpointGroups`](endpointgroups/README.md), [`IdentityProviders`](identityproviders/README.md), [`FederationProtocols`](federationprotocols/README.md) and [`ServiceProviders`](serviceproviders/README.md) cover OS-EP-FILTER and OS-FEDERATION. [Identity finding](../../docs/finding-identities.md) explains name and ID resolution.\n\n")
	case "compute/v2":
		out.WriteString("Package docs describe the service and its resources (`go doc ./compute/v2/...`). [Wait policies](../../docs/service-waits.md), [identity finding](../../docs/finding-identities.md), [project quotas](quotasets/README.md), [limits](limits/README.md), [server tags](tags/README.md) and [instance actions](instanceactions/README.md) cover shared behavior.\n\n")
	case "blockstorage/v2":
		out.WriteString("`Volumes.MetadataIn(ctx, ref)` and `Snapshots.MetadataIn(ctx, ref)` resolve an ID or name once and expose the same Get, Merge, Replace, and DeleteKeys operations. Merge uses POST merge; Replace uses PUT full replacement. Nil/empty maps still send an explicit metadata object. Nil DeleteKeys deletes all keys, an empty slice makes no requests, and other slices delete in input order and return results before failure. Results contain actual metadata, raw bodies, headers, and success codes without a Resource cache. [Shared metadata](../metadata/README.md), [Volumes](volumes/README.md), and [Snapshots](snapshots/README.md) describe Python mappings, ETags, options, and partial success. Backup metadata child routes are outside this contract.\n\n")
		out.WriteString("[Native v2 calls](native-calls.md) documents only input, listing, and decoding differences between generated methods in the deprecated v2 package and native v3 calls.\n\n")
		out.WriteString("[Cinder v2 Python Proxy mappings](python-parity-volumes.md) covers volume, snapshot, and consistency group snapshot methods and unresolved behavior.\n\n")
		out.WriteString("[Cinder v2 resource mappings](python-parity-resources.md) covers backups, transfers, quotas, services, and other non-volume/snapshot resources, including unmapped methods.\n\n")
	case "blockstorage/v3":
		out.WriteString("Package docs describe the service and its resources (`go doc ./blockstorage/v3/...`). [Wait policies](../../docs/service-waits.md), [identity finding](../../docs/finding-identities.md), [shared metadata](../metadata/README.md), [project quotas](quotasets/README.md), [limits](limits/README.md) and [noauth clients](../noauth/README.md) cover shared behavior.\n\n")
	case "network/v2":
		out.WriteString("Package docs describe the service and its resources (`go doc ./network/v2/...`). Guides: [identity finding](../../docs/finding-identities.md), [selective reads and conditional deletion](python-read-delete.md), [conditional updates](revision-updates.md), [security group listing](extensions/security/groups/listing/README.md), [router listing](extensions/layer3/routers/listing/README.md), [trunk listing](extensions/trunks/listing/README.md), [network listing](networks/listing/README.md), [subnet-pool listing](extensions/subnetpools/listing/README.md), [QoS policy listing](extensions/qos/policies/listing/README.md), [address-group listing](extensions/security/addressgroups/listing/README.md), [Body filters](../../docs/listing.md#explicit-native-body-filters), [subnets](subnets/README.md), [pinned AST manifest](../../api/openstacksdk/resources/network/v2/subnet.json), [minimum bandwidth](qos-minimum-bandwidth-records-python.md), [minimum packet rate](qos-minimum-packet-rate-records-python.md), [packet rate limits](qos-packet-rate-limit-records-python.md), [rule types](qos-rule-types-python.md), [Security group lists](security-group-list-python.md), [security rule lists](security-group-rule-list-python.md), [router reads](router-read-records-python.md), [RBAC mutations](rbac-policy-mutations-python.md), [RBAC](rbac-policy-python.md), [bandwidth limits](qos-bandwidth-limit-records-python.md), [DSCP](extensions/qos/rules/dscp-marking-python.md), [trunk lists](trunk-list-python.md), [address group lists](address-group-list-python.md), [Address scopes](address-scope-records-python.md), [subnet pools](subnet-pool-records-python.md), [QoS policies](qos-policy-records-python.md), [Security lookup](security-find-python.md), [trunk/address lookup](trunk-address-find-python.md), [router interfaces/gateways](router-interfaces-python.md), [Core lookup](find-core-resources-python.md), [router routes/gateways](router-actions-python.md), [trunk/address group actions](trunk-address-actions-python.md), [seven tag APIs](tags-python.md), [Two Python port-forwarding names](port-forwarding-python.md), [Networks](networks/python-mutations.md), [ports](ports/python-mutations.md), [subnets](subnets/python-mutations.md), [routers](extensions/layer3/routers/python-mutations.md), [floating IPs](extensions/layer3/floatingips/python-mutations.md), [security groups](extensions/security/groups/python-mutations.md), [security rules/bulk creation](extensions/security/rules/python-mutations.md), [resource creation/default deletion](python-resource-mutations.md), [selected reads/deletion](python-read-delete.md), [Native CRUD](native-crud.md), [Native Neutron administration](native-admin.md), [Native BGP and BGP VPN calls](native-bgp.md), [LBaaS, flavors, and metering](python-parity-lbaas-metering.md), [SFC and TaaS mappings](python-parity-sfc-tap.md), [L3, QoS, and FWaaS mappings](python-parity-l3-qos-fw.md), [Neutron core mappings](python-parity-core.md), [VPN and BGP mappings](python-parity-vpn-bgp.md), [Packet-rate rule mutations](extensions/qos/rules/packet-rate-mutations-python.md), [Project quotas](extensions/quotas/README.md)." + "\n\n")
	case "loadbalancer/v2":
		out.WriteString("`conn.LoadBalancerProjectQuotas(ctx, project)` and `CurrentLoadBalancerProjectQuotas(ctx)` fix the Octavia quota project. [Quotas](quotas/README.md) covers Get/Update/Reset, global Defaults, separate ListProjects/AllProjects, and official lbaas/native URL differences.\n\n")
	case "sharedfilesystems/v2":
		out.WriteString("`conn.SharedFileSystemProjectQuotas(ctx, project)` and `CurrentSharedFileSystemProjectQuotas(ctx)` fix the Manila quota project. [Quotas](quotasets/README.md) covers Get/Defaults/Detail/Update/Reset and microversion-specific routes. These SDK-owned APIs are absent from pinned Gophercloud.\n\n")
		out.WriteString("`service.QuotaClassSets.InClass(ctx, \"default\")` fixes the class name for Get/Update, without project resolution or List/Reset. [Quota classes](quotaclasssets/README.md) covers Python mappings, typed limits, and extension inputs.\n\n")
		out.WriteString("Typed `ShareAccessRules.InShare(ctx, share)` lists accept `request.MaxItems(n)` and `request.Paginated(false)` consumption controls. Modern access endpoints return one collection, so no next links are followed and caps are not sent as wire limits. Calls recheck numeric version 2.45 or later and actual Manila service-type/version headers, preserving canonical lowercase response IDs and parents. [Access rules](shareaccessrules/README.md) covers Allow/Deny, waits, response evidence, and Python differences.\n\n")
	case "dns/v2":
		out.WriteString("`conn.DNSProjectQuotas(ctx, project)` and `CurrentDNSProjectQuotas(ctx)` fix the Designate quota project. [Quotas](quotas/README.md) covers Get/PATCH Update/DELETE Reset and sudo-project/all-projects headers. There is no separate defaults endpoint or project quota list.\n\n")
	case "containerinfra/v1":
		out.WriteString("`conn.ContainerInfraProjectQuotas(ctx, project)` and `CurrentContainerInfraProjectQuotas(ctx)` fix the project; `ForResource(quotas.Cluster)` selects the quota. [Quotas](quotas/README.md) covers Get/Create/PATCH Update/DELETE, explicit hard limits, API.List/All paging/all_tenants, and the absence of Python quota declarations.\n\n")
	case "db/v1":
		out.WriteString("`Instances.IsRootEnabled(ctx, instanceID)` returns the native root-access boolean. HTTP, transport, and JSON errors preserve their causes without panic; only literal true in a successful `rootEnabled` response becomes true. [Root access](instances/root-access.md) explains response objects, errors, and differences from the Python Resource method.\n\n")
		out.WriteString("`Databases.InInstance(ctx, instanceRef)` and `Users.InInstance(ctx, instanceRef)` fix the instance once. Pinned native APIs lack per-child fetches, so Get/Find searches that instance's list for exact names. Create and CreateBatch send array requests and return errors only because asynchronous responses contain no object. See [databases](databases/README.md) and [users](users/README.md) for identifiers, deletion, and limitations.\n\n")
	case "objectstorage/v1":
		out.WriteString("Package docs describe the service, accounts, containers and objects (`go doc ./objectstorage/v1/...`). Guides: [accounts](accounts/README.md), [containers](containers/README.md), [objects](objects/README.md), [object creation](objects/create.md), [directory markers](objects/directory-marker.md), [reads](objects/read.md), [deletion](objects/delete.md), [waits](objects/wait.md), [capabilities](info.md), [signing](signing.md) and [temp URL keys](temp_url_key.md).\n\n")
	}
	var example *collectionRecord
	for i := range g.collections {
		record := &g.collections[i]
		if record.Model != "" && record.Kind != "service_info" && record.Kind != "named_resource" && record.Scope == "" && record.Package != "github.com/JSYoo5B/go-openstacksdk/image/v2/serviceinfo" && strings.HasPrefix(record.Package, "github.com/JSYoo5B/go-openstacksdk/"+key+"/") {
			example = record
			if strings.TrimPrefix(record.Package, "github.com/JSYoo5B/go-openstacksdk/"+key+"/") == exampleResources[parts[0]] {
				break
			}
		}
	}
	out.WriteString("## Go usage\n\n```go\n")
	fmt.Fprintf(&out, "// Inside a function with context.Context ctx and *openstack.Connection conn.\nservice, err := conn.%s(ctx)\nif err != nil { return err }\n", method)
	if example != nil {
		field := registryField(strings.TrimPrefix(example.Package, "github.com/JSYoo5B/go-openstacksdk/"+key+"/"))
		accessor := "service." + field + ".Resources"
		finder := "service." + field
		if example.Source == "sdk_owned" {
			finder = accessor
		}
		if example.Kind == "compound_identity" {
			accessor += "()"
			finder = accessor
		}
		fmt.Fprintf(&out, "for value, err := range %s.List(ctx) {\n    if err != nil { return err }\n    fmt.Println(value)\n}\n", accessor)
		if example.Find {
			fmt.Fprintf(&out, "value, err := %s.Find(ctx, resource.Name(\"example\"))\nif err != nil { return err }\n_ = value\n", finder)
		}
	} else {
		if parts[0] == "metric" {
			out.WriteString("data, err := service.Metrics.Query(ctx, metrics.QueryOpts{Query: \"up\"})\nif err != nil { return err }\nfmt.Println(data)\n")
		} else if err := g.writeListExample(&out, key, paths); err != nil {
			return err
		}
	}
	out.WriteString("```\n\nExamples use `fmt` and `github.com/JSYoo5B/go-openstacksdk/resource`.\n\n")
	if parts[0] == "metric" {
		out.WriteString("`metrics` refers to `github.com/JSYoo5B/go-openstacksdk/metric/v1/metrics`.\n\n")
	}
	out.WriteString("## Resources\n\n| Service field | API package | Common policies and scope |\n|---|---|---|\n")
	for _, path := range paths {
		var policies []string
		apiFile := "api_generated.go"
		for _, record := range g.collections {
			if record.Package != "github.com/JSYoo5B/go-openstacksdk/"+key+"/"+path || record.Model == "" {
				continue
			}
			if record.Source == "sdk_owned" {
				apiFile = "api.go"
			}
			if record.Package == "github.com/JSYoo5B/go-openstacksdk/image/v2/serviceinfo" {
				switch record.Model {
				case "Store":
					policies = append(policies, "`ListStores/AllStores(ctx)`: store lists and optional details; no Resources/CRUD/Find/Wait")
				case "ImportInfo":
					policies = append(policies, "`GetImportInfo(ctx)`: service import methods; preserves raw fields, headers, and status")
				case "UsageInfo":
					policies = append(policies, "[`GetUsageInfo(ctx)`](serviceinfo/usage.go): authenticated-project usage/limits singleton; [usage policies](serviceinfo/usage.md); no ID/list/mutation/status waits")
				}
				continue
			}
			label := "Resources"
			if record.Scope != "" {
				label = record.Scope + "(ctx, parent)"
			}
			if record.Kind == "string_set" {
				policies = append(policies, fmt.Sprintf("`%s`: read/add/check/replace/delete string sets; no Collection/status waits", label))
				continue
			}
			if record.Kind == "service_info" {
				policies = append(policies, "`Get(ctx)`: service build-info singleton; no ID/list/mutation/status waits")
				continue
			}
			if record.Kind == "named_resource" {
				policies = append(policies, "`Create/Get/Update/Delete(ctx, namespace, options...)`, `List/All(ctx, options...)`: literal namespace names and concrete defaults; Create sends Properties/Objects/Tags/ResourceTypeAssociations in one POST; explicit PUT replacement; [Python/Go comparison](metadefnamespaces/README.md); no Resources/Find/status waits")
				continue
			}
			if record.Kind == "scoped_named_resource" {
				policies = append(policies, "`InNamespace(ctx, namespace)`: fixed literal scope without HTTP; `Create/Get/Update/Delete(ctx, name, options...)`, `DeleteAll/List/All(ctx, options...)`; concrete defaults, explicit PUT replacement, finite lists, local MaxItems; individual Delete ignores 404 by default, DeleteAll treats 404 as an error; [Python/Go comparison](metadefobjects/README.md); no Resources/Find/status waits")
				continue
			}
			if record.Kind == "scoped_definition" {
				policies = append(policies, "`InNamespace(ctx, namespace)`: fixed literal scope without HTTP; `Create/Get/Update/Delete(ctx, name, options...)`, `DeleteAll/List/All(ctx, options...)`; flat JSONSchema with required Type/Title, explicit PUT replacement, finite dictionary lists, independent Key, local MaxItems; optional Get resource_type; individual Delete ignores 404 by default, DeleteAll treats 404 as an error; [Python/Go comparison](metadefproperties/README.md); no Resources/Find/status waits")
				continue
			}
			if record.Kind == "scoped_tag_resource" {
				policies = append(policies, "`InNamespace(ctx, namespace)`: fixed literal scope without HTTP; bodyless `Create`, `Get/Update/Delete(ctx, name, options...)`, `Set(ctx, names, options...)`, `DeleteAll/List/All(ctx, options...)`; Set defaults to append=false and empty input does not clear the database; actual limit/marker/sort queries, raw-name continuation for positive limits, local MaxItems; both Delete methods treat 404 as an error; [Python/Go comparison](metadeftags/README.md); no Resources/Find/status waits")
				continue
			}
			if record.Kind == "catalog_and_association" {
				policies = append(policies, "Global `List/All(ctx, options...)`: resource-type catalog; `InNamespace(ctx, namespace).Create/Delete(ctx, name, options...)` and `List/All(ctx, options...)`: associations; both finite lists share concrete ListOpts and local MaxItems without queries/paging; Prefix/PropertiesTarget distinguish omission from empty; Delete ignores clean 404 by default and removes only the association; [Python/Go comparison](metadefresourcetypes/README.md); no Resources/single Get/Update/Find/status waits")
				continue
			}
			if record.Kind == "store_defaults" {
				policies = append(policies, "`List/All`, `GetGlobalDefault`, `GetPreferred`: lists and two fixed reads; no Resources/CRUD/Find/Wait")
				continue
			}
			if record.Kind == "effective_project_quota" {
				policies = append(policies, "`Get(ctx)`: authenticated-project effective quota; `InProject(ctx, ID)`: Get/replacement Update/override Delete; no list/Find/Wait")
				continue
			}
			if record.Kind == "secret_acl" {
				policies = append(policies, "`InSecret(ctx, ref)`: Python secret ACL Get, PUT Set/Update, ignore-missing Delete; absent attributes cause no HTTP; no Resources/list/Find/Wait")
				continue
			}
			if record.Kind == "secret_consumer" {
				policies = append(policies, "`InSecret(ctx, ref)`: association Create/Delete and offset List/All; actual secret responses; no consumer ID/Resources/Find/Wait")
				continue
			}
			if record.Kind == "queue_subscription" {
				policies = append(policies, "`InQueue(ctx, queueName)`: fixed-name Create/Get/List/All/Delete; no Resources/Find/Wait/Update")
				continue
			}
			if record.Kind == "list_only" {
				policies = append(policies, "`List/All`: list only; no individual reads/mutations/status waits")
				continue
			}
			if record.Kind == "scoped_list_only" {
				policies = append(policies, "`InCluster(ctx, parent, path)`: fixed-cluster/JSONPath List/All; preserves raw node values; no individual reads/mutations/status waits")
				continue
			}
			if record.Kind == "policy_binding" {
				policies = append(policies, "`InCluster(ctx, parent)`: fixed-cluster policy reads/lists/name lookup; preserves separate binding IDs; no mutations/default status")
				continue
			}
			if record.Kind == "async_resource" {
				policies = append(policies, "`Resources`: ID reads, lists, name lookup, status waits; `API.Delete` returns asynchronous action Submission; Collection.Delete is unsupported")
				continue
			}
			if record.Kind == "singleton" {
				operations := "Get·Defaults·Detail·Update·Reset"
				if strings.HasSuffix(record.Package, "/blockstorage/v3/quotasets") {
					operations = "Get·Defaults·Usage·Update·Reset"
				} else if strings.HasSuffix(record.Package, "/network/v2/extensions/quotas") {
					operations = "Get·Defaults·Detail·Update·Delete"
				} else if strings.HasSuffix(record.Package, "/loadbalancer/v2/quotas") {
					operations = "Get/Update/Reset; Defaults is global"
				} else if strings.HasSuffix(record.Package, "/dns/v2/quotas") {
					operations = "Get·Update·Reset"
				}
				policies = append(policies, fmt.Sprintf("`%s`: %s for a fixed project; no List/Find/Wait", label, operations))
				continue
			}
			if record.Kind == "named_singleton" {
				policies = append(policies, "`InClass(ctx, className)`: fixed-name Get/Update; no project resolution/List/Reset/Wait")
				continue
			}
			if record.Kind == "project_limits" {
				policies = append(policies, "`Fetch(ctx)` / `InProject(ctx, parent).Get(ctx)`: current/fixed-project read-only singleton; no List/Find/Wait/mutations")
				continue
			}
			if record.Kind == "project_resource_quota" {
				policies = append(policies, "`InProject(ctx, parent).ForResource(name)`: fixed-project/resource Get/Create/Update/Delete; `API.List/All`: quota pages; no name Find/Wait")
				continue
			}
			if record.Kind == "compound_identity" {
				label = "Resources() / InStack(ctx, ref) / ForStack(identity)"
			}
			if record.Kind == "event_log" {
				policies = append(policies, "`InStack(ctx, ref) / ForStack(identity)`: stack/resource event lists and resource_name+eventID reads; no name Find/mutations/waits")
				continue
			}
			if record.Kind == "compound_child" {
				policies = append(policies, "`InStack(ctx, ref) / ForStack(identity)`: resource_name reads, lists, name resolution, metadata, health, waits; verifies actual nested owners")
				continue
			}
			features := []string{"ID reads", "lists"}
			if record.Find {
				features = append(features, "name lookup")
			}
			if record.Delete {
				features = append(features, "deletion/deletion waits")
			}
			if record.Wait {
				features = append(features, "status waits")
			}
			policies = append(policies, fmt.Sprintf("`%s`: %s", label, strings.Join(features, ", ")))
			if record.MetadataScope != "" {
				policies = append(policies, fmt.Sprintf("`%s(ctx, ref)`: fixed metadata Get/Merge/Replace/DeleteKeys; SDK-owned requests and actual metadata responses", record.MetadataScope))
			}
			if record.ServiceWait != "" {
				policies = append(policies, "`WaitForState/WaitForDelete`: service-specific defaults and caller options")
			}
			if record.TaskWait != "" {
				policies = append(policies, "`WaitForTask/WaitForTaskState`: one time budget, recreation after 396, actual partial results")
			}
		}
		policy := strings.Join(policies, "; ")
		if policy == "" {
			policy = "API operations; no common Collection policies"
		}
		// Owned facades need not invent an api_generated.go file. Prefer their
		// actual usage page when the conventional implementation file is absent.
		if _, err := os.Stat(filepath.Join(g.root, key, path, apiFile)); os.IsNotExist(err) {
			if _, err := os.Stat(filepath.Join(g.root, key, path, "README.md")); err == nil {
				apiFile = "README.md"
			} else if candidates, err := filepath.Glob(filepath.Join(g.root, key, path, "*api*.go")); err == nil {
				for _, candidate := range candidates {
					if !strings.HasSuffix(candidate, "_test.go") {
						apiFile = filepath.Base(candidate)
						break
					}
				}
			}
		}
		fmt.Fprintf(&out, "| `%s` | [%s](%s/%s) | %s |\n", registryField(path), path, path, apiFile, policy)
	}
	out.WriteString("\nShared rules for options, name lookup, listing, parent scopes, waits and microversions are in [common operations](../../docs/common-operations.md), [finding identities](../../docs/finding-identities.md), [listing](../../docs/listing.md), [scoped resources](../../docs/scoped-resources.md), [service waits](../../docs/service-waits.md) and [microversions](../../docs/microversions.md). Run `go doc` on a package for its calls; Python openstacksdk mappings and contracts are recorded in [the review ledger](../../api/sdk_reviews.json).\n")
	return os.WriteFile(filepath.Join(g.root, key, "README.md"), []byte(out.String()), 0644)
}

// Where no common Collection exists yet, show a real typed list operation.
func (g *generator) writeListExample(out *strings.Builder, key string, paths []string) error {
	for _, path := range paths {
		file, err := parser.ParseFile(token.NewFileSet(), filepath.Join(g.root, key, path, "api_generated.go"), nil, 0)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return err
		}
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv == nil || !strings.HasPrefix(fn.Name.Name, "List") {
				continue
			}
			params := fn.Type.Params.List
			if len(params) != 1 {
				if len(params) != 2 {
					continue
				}
				if _, ok := params[1].Type.(*ast.Ellipsis); !ok {
					continue
				}
			}
			fmt.Fprintf(out, "for value, err := range service.%s.%s(ctx) {\n    if err != nil { return err }\n    fmt.Println(value)\n}\n", registryField(path), fn.Name.Name)
			return nil
		}
	}
	out.WriteString("// Select operations and concrete options from the resource table below.\nfmt.Println(service.RawClient().Endpoint)\n")
	return nil
}
